import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"kiwa v1.18 released — Blockchain 深化 (Reth + Foundry invariant/fuzz + Alloy helpers + dApp e2e reorg)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.18/gh-discussions-announcement.md","filePath":"announcements/v1.18/gh-discussions-announcement.md"}'),n={name:"announcements/v1.18/gh-discussions-announcement.md"};function d(c,e,i,s,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="kiwa-v1-18-released-—-blockchain-深化-reth-foundry-invariant-fuzz-alloy-helpers-dapp-e2e-reorg" tabindex="-1">kiwa v1.18 released — Blockchain 深化 (Reth + Foundry invariant/fuzz + Alloy helpers + dApp e2e reorg) <a class="header-anchor" href="#kiwa-v1-18-released-—-blockchain-深化-reth-foundry-invariant-fuzz-alloy-helpers-dapp-e2e-reorg" aria-label="Permalink to &quot;kiwa v1.18 released — Blockchain 深化 (Reth + Foundry invariant/fuzz + Alloy helpers + dApp e2e reorg)&quot;">​</a></h1><p>v1.18 is out. After v1.17&#39;s Observability v2 vertical (<code>@kiwa-test/observability</code> v2.0 unifying Grafana dashboards + Prometheus AlertManager + trace flame graphs + log correlation), v1.18 turns to <strong>the Rust blockchain testing stack</strong> — Reth (Rust Ethereum Execution client) integration, Foundry-rs invariant / fuzz runner depth, Alloy encoder helpers (EIP-712 / Multicall3 / Permit2), and dApp e2e reorg semantics — four additional axes on top of the v1.10 <code>kiwa::contract::foundry</code> + <code>kiwa::contract::alloy</code> foundation.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ul><li><strong><code>kiwa-test-rs</code> v0.5.0</strong> (minor bump from v0.4.2). 3 additional axes over the v0.4 contract layer. Zero breaking changes to v0.4 (<code>kiwa::contract::foundry::Anvil</code> + <code>kiwa::contract::foundry::FoundryEnv</code> + <code>kiwa::contract::alloy::SolAbi</code> + <code>kiwa::contract::alloy::Signer</code> + <code>kiwa::contract::alloy::keccak256</code>) — the <code>foundry.rs</code> file moves to <code>foundry/mod.rs</code> and <code>alloy.rs</code> moves to <code>alloy/mod.rs</code>, but every public re-export path stays the same, so <code>use kiwa::contract::foundry::FoundryEnv;</code> callers do not touch a line. <ul><li><code>kiwa::contract::reth</code> — new module behind feature <code>contract-reth</code> (default OFF). <code>RethBinary::detect</code> performs a lightweight PATH check for the <code>reth</code> CLI; when absent, helpers return <code>skipped</code> shape so test suites gracefully skip in environments without the toolchain provisioned. <code>RethNode::spawn</code> wraps <code>reth node --dev</code> in a <code>Drop</code>-based subprocess handle. <code>reth_reorg(endpoint, blocks)</code> drives an N-block reorg through the <code>debug_setHead</code> JSON-RPC method (which reth exposes in dev mode). <code>fidelity_matrix()</code> returns a 7-row anvil ↔ reth expectation table for the JSON-RPC surface both dev chains implement (<code>eth_blockNumber</code> / <code>eth_chainId</code> / <code>eth_getBalance</code> / <code>eth_gasPrice</code> / <code>eth_call</code> / <code>net_version</code> / <code>web3_clientVersion</code>). Pure Rust — no alloy crate family dependency (subprocess plumbing lives in <code>std::process</code>, JSON-RPC payloads are hand-encoded strings).</li><li><code>kiwa::contract::foundry::invariant</code> — new submodule under the existing <code>contract-foundry</code> feature. Drives <code>forge test --match-contract Invariant*</code> with a decoded 10_000 run + fuzz seed determinism gate (seed feeds through <code>FOUNDRY_INVARIANT_SEED</code> env var + Cargo.toml <code>[profile.default.invariant]</code> seed row so re-runs replay). Ships a shrink parser that maps <code>forge test</code>&#39;s &quot;counter-example shrunk to&quot; output to a structured <code>InvariantCounterExample { calls: Vec&lt;Call&gt;, revert: Option&lt;String&gt; }</code> shape. <code>coverage_feed()</code> translates invariant + fuzz coverage lcov output into the <code>@kiwa-test/quality-metrics</code> release gate 7-axis JSON shape so the mock harness and dogfood app cross-report.</li><li><code>kiwa::contract::alloy::helpers</code> — new submodule under the existing <code>contract-alloy</code> feature. <code>Eip712TypedData::build(domain, primary_type, message)</code> builds a 4-layer typed data digest (domain separator + typeHash + structHash + digest per EIP-712). <code>Multicall3::encode(calls)</code> writes <code>aggregate3(Call3[])</code> calldata that packs N <code>eth_call</code>-shaped calls into 1 transaction for the Multicall3 contract at <code>0xcA11bde05977b3631167028862bE2a173976CA11</code>. <code>Permit2::permit_witness_transfer_from(spec)</code> encodes the SignatureTransfer + witness verify pattern from <code>permit2.uniswap.org</code>. Pure Rust — same principle as the parent <code>alloy</code> module: no alloy crate dependency; consumers plug encoded bytes into whichever Provider they build outside kiwa.</li></ul></li><li><strong><code>examples/dogfood-reth-node-test</code></strong> — Reth NodeBuilder dev chain driven behind a provider-neutral <code>RethAdapter</code>. <code>makeMockAdapter</code> spins up an anvil dev chain over <code>kiwa::contract::foundry::Anvil</code> and drives 5 ERC-20 transactions through the alloy Provider surface; <code>makeRealAdapter</code> spawns <code>reth node --dev</code> through the new <code>kiwa::contract::reth::RethNode</code> handle and drives the same 5 tx. A 3-block reorg exercise via <code>reth_reorg</code> + <code>debug_setHead</code> closes both loops. The fidelity harness produces a <code>RethFidelityReport</code> covering the 7-row anvil ↔ reth JSON-RPC matrix. 7-axis release gate verdict PASS. 32 cargo test.</li><li><strong><code>examples/dogfood-foundry-invariant-fuzz</code></strong> — 3 Solidity contract fixtures (<code>ERC20</code> + <code>Vault</code> + <code>Router</code>) with a per-contract invariant runner. <code>Invariant_ERC20_TotalSupply</code> runs <code>invariant_total_supply_constant</code> for 10_000 forge runs at seed <code>0xdeadbeef</code>. <code>Invariant_Vault_NoUnderflow</code> runs <code>invariant_no_underflow</code> for 10_000 runs asserting <code>sum(user balances) &lt;= totalDeposit</code>. <code>Invariant_Router_NoDrain</code> runs <code>invariant_no_drain</code> for 10_000 runs asserting <code>router.balance == 0</code> after each swap. When the invariant breaks, the <code>kiwa::contract::foundry::invariant</code> shrink parser decodes the counter-example call list into a structured <code>InvariantCounterExample</code>. <code>coverage_feed</code> roll up feeds the 7-axis release gate coverage row. 21 cargo test.</li><li><strong><code>examples/dogfood-dapp-e2e-reorg</code></strong> — Next.js 15 (App Router) frontend + viem + wagmi wallet connect + <code>@kiwa-test/dapp</code> Playwright fixture + anvil mainnet fork (block 20_000_000). <code>@kiwa-test/dapp</code> gains 2 new named exports <code>snapshotChain(client)</code> + <code>revertChain(client, snapshotId)</code> (implemented over <code>anvil_snapshot</code> + <code>anvil_revert</code> JSON-RPC methods) — the reorg dogfood app + tutorial 27 share the same reorg drivers. 4 reorg scenario specs: <code>pending-tx-rollback</code> (user tx confirmed at block N, chain reorgs to N-2, tx pending again) / <code>receipt-invalidation</code> (tx receipt fetched then chain reverts, refetch returns null) / <code>event-log-rewind</code> (subscribed logs from block N drop after reorg to N-3) / <code>nonce-desync</code> (account nonce advances to 5 then chain rewinds to nonce 3). Fidelity harness compares mock vs anvil fork behavior for each scenario. 7-axis release gate verdict PASS. 26 Playwright test.</li><li><strong>docs</strong> — 3 new tutorials (25 Reth node test / 26 Foundry invariant + fuzz / 27 dApp e2e reorg) + additive migration guide v1.17 → v1.18 + concept doc <code>blockchain-testing.md</code> documenting the <strong>4 additional axes × 6 semantic axes</strong> (chain state (snapshot / revert / reorg) / EL client integration (anvil ↔ reth fidelity) / fuzz shrinker (invariant counter-example decode) / reorg semantics (pending tx / receipt / event log / nonce desync)) as the SSOT. VitePress sidebar refreshed with a new <code>Blockchain 深化 (v1.18)</code> tutorial section; gh-pages published via <code>/docs-publish-kiwa</code>.</li></ul><h2 id="numbers" tabindex="-1">Numbers <a class="header-anchor" href="#numbers" aria-label="Permalink to &quot;Numbers&quot;">​</a></h2><ul><li><strong>6 sub-Issues resolved</strong> (#793-#798)</li><li><strong>6 PRs merged</strong> (#799-#803 + this publish PR)</li><li><strong>1 crate minor bump</strong> (<code>kiwa-test-rs</code> v0.4.2 → v0.5.0 with crates.io publish)</li><li><strong>3 new dogfood apps</strong> with fidelity reports feeding the 7-axis release gate</li><li><strong>79 new tests</strong> across the 3 dogfood apps (32 cargo + 21 cargo + 26 Playwright) all pass</li></ul><h2 id="_8-milestone-streak" tabindex="-1">8-milestone streak <a class="header-anchor" href="#_8-milestone-streak" aria-label="Permalink to &quot;8-milestone streak&quot;">​</a></h2><p>v1.11 (release gate) → v1.12 (non-determinism) → v1.13 (time-axis) → v1.14 (horizontal expansion) → v1.15 (AI-LLM depth) → v1.16 (component depth) → v1.17 (Observability v2) → <strong>v1.18 (Blockchain depth)</strong>. Every milestone since v1.11 has landed 6 sub-Issues in full.</p><h2 id="v2-0-candidates" tabindex="-1">v2.0 candidates <a class="header-anchor" href="#v2-0-candidates" aria-label="Permalink to &quot;v2.0 candidates&quot;">​</a></h2><ul><li>Multi-version Vitest matrix (Vitest 1.x vs 2.x vs 3.x parity)</li><li>Desktop (Electron / Tauri) + mobile (React Native / Expo) adapters</li><li>Framework depth (SolidJS / Fresh / HonoJS)</li><li>Coverage 100% milestone</li><li>Cache / Data depth (Dragonfly / Materialize / Neon)</li><li>L2 depth (Base / Arbitrum / Optimism / Scroll block-space fidelity)</li><li>ZK depth (Noir / Circom / RISC Zero test harness)</li></ul><p>Feedback welcome on which of these should land next.</p>',11)])])}const g=o(n,[["render",d]]);export{p as __pageData,g as default};
